export const getReversePaymentUrl = (paymentId: number,) => {




  return `/api/finance/payments/${paymentId}/void`
}

/**
 * Owner, manager, or accountant only. Locks the invoice row and reverses the exact payment amount from invoice and associated installment balances in one transaction. The payment row remains unchanged; the reason and immutable before/after payment, invoice, and installment snapshots are written to the clinic audit log. Repeated reversals conflict. Reversed payments are omitted from finance revenue reports and remain visible in invoice correction history.
 * @summary Reverse a payment without deleting or editing it
 */
export const reversePayment = async (paymentId: number,
    financeCorrectionInput: FinanceCorrectionInput, options?: Parameters<typeof customFetch>[1]): Promise<Invoice> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Invoice>(getReversePaymentUrl(paymentId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(financeCorrectionInput)
  }
);}





